<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><div><h2>Circulation</h2><p class="text-muted">Manage check-out, check-in, returns, and overdue monitoring.</p></div><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=transactions&action=checkout">+ Check out book</a></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Book</th><th>Borrower</th><th>Borrower ID</th><th>Due date</th><th>Status</th><th>Fine</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= Security::e($r['title']) ?></td><td><?= Security::e($r['borrower_name']) ?></td><td><?= Security::e($r['borrower_id']) ?></td><td><?= Security::e($r['due_date']) ?></td><td><?= Security::e(ucwords(str_replace('_',' ',$r['status']))) ?></td><td>₱<?= number_format((float)$r['fine'],2) ?></td><td class="d-flex gap-1"><?php if($r['status']==='checked_out'):?><form method="post" action="<?= BASE_URL ?>/?page=transactions&action=checkin"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-success">Check in</button></form><form method="post" action="<?= BASE_URL ?>/?page=transactions&action=markCondition"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><select name="condition" class="form-select form-select-sm"><option value="damaged">Damaged</option><option value="lost">Lost</option></select><button class="btn btn-sm btn-outline-danger">Mark</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
